buttons:

  .tllgbnr_container {
    background-color: #fff;
    display: flex;
    justify-content: flex-start;
    align-items: center;
    text-decoration: none;
    box-sizing: border-box;
    min-height: 36px;
  }

  @media screen and (max-width: 767px) {
    .tllgbnr_container {
      flex-flow: row wrap;
    }
  }

  .tllgbnr_text {
    display: none;
    padding: 4px 0;
    font-size: 14px;
    line-height: 20px;
    color: #737476;
    margin-right: 6px;
    font-weight: 500;
  }

  .tllgbnr_logo {
    display: block;
    max-width: 88px;
    height: 32px;
    padding: 4px;
    box-sizing: border-box;
  }

  @media screen and (max-width: 767px) {
    .tllgbnr_container {
      width: 130vw;
      margin-left: -16px;
      padding: 0 16px;
    }

    .tllgbnr_text {
      display: block;
    }
  }

  /* Tooltip container */
  .tllgbnr_tooltip {
    margin: 3px 0;
    height: 16px;
    width: 14px;
    position: relative;
    display: inline-block;
    vertical-align: top;
  }

  .tllgbnr_tooltip .tllgbnr_tooltiptext {
    font-weight: 400;
    text-align: left;
    max-width: 311px;
    min-width: 300px;
    font-size: 10px;
    line-height: 14px;
    visibility: hidden;
    display: block;
    background: #242628;
    border-radius: 4px;
    color: #fff;
    opacity: .8;
    padding: 12px 16px;
    position: absolute;
    z-index: 0;
  }

  .tllgbnr_tooltip .tllgbnr_tooltiptext::after {
    content: "";
    position: absolute;

    margin-left: -5px;
    border-width: 5px;
    border-style: solid;

  }

  @media screen and (max-width: 767px) {
    .tllgbnr_tooltip .tllgbnr_tooltiptext::after {
      top: 100%;
      left: 85%;
      border-color: #242629 transparent transparent transparent;
    }

    .tllgbnr_tooltip .tllgbnr_tooltiptext {
      bottom: 150%;
      right: -30px;
      max-width: 280px;
      min-width: 250px;
    }
  }

  @media screen and (min-width: 768px) {
    .tllgbnr_tooltip .tllgbnr_tooltiptext {
      top: 150%;
      left: -258px;
    }

    .tllgbnr_tooltip .tllgbnr_tooltiptext::after {
      bottom: 100%;
      left: 88%;
      border-color: transparent transparent #242629 transparent;
    }
  }

  @media screen and (max-width: 320px) {
    .tllgbnr_tooltip .tllgbnr_tooltiptext {
      width: 220px;
      max-width: 250px;
      min-width: 220px;
    }

    .tllgbnr_tooltip .tllgbnr_tooltiptext::after {
      left: 78%;
    }
  }

  #tllgbnr_legalCheckbox {
    visibility: hidden;
    position: absolute;
  }

  @media screen and (max-width: 767px) {
    #tllgbnr_legalCheckbox {
      visibility: hidden;
      position: absolute;
    }

    #tllgbnr_legalCheckbox:checked~.tllgbnr_tooltiptext {
      visibility: visible;
    }
  }

  @media screen and (min-width: 767px) {
    #tllgbnr_legalCheckbox:hover~.tllgbnr_tooltiptext {
      visibility: visible;
    }
  }


  .tllgbnr_legalToggle {
    position: absolute;
    width: 100%;
    display: flex;
    justify-content: center;
    align-items: center;
    font-size: 12px;
    line-height: 16px;
    font-weight: 500;
    cursor: pointer;
    z-index: 0;
  }

